package com.dlxyuki.wms.pickingbol;
import static org.assertj.core.api.Assertions.assertThat;import java.io.ByteArrayInputStream;import java.util.*;import org.apache.poi.ss.usermodel.CellType;import org.apache.poi.xssf.usermodel.XSSFWorkbook;import org.junit.jupiter.api.Test;import org.springframework.web.bind.annotation.*;
class PickingListReadContractTest{@Test void routesAndWorkbookContract()throws Exception{assertThat(PickingBolController.class.getAnnotation(RequestMapping.class).value()).containsExactly("/api/v1/picking-lists");assertThat(PickingBolController.class.getDeclaredMethod("export",long.class,com.dlxyuki.wms.user.UserAccount.class).getAnnotation(GetMapping.class).value()).containsExactly("/{pickingId}/xlsx");Map<String,Object>p=Map.of("picking_no","PK-1","outbound_order_id",9L);Map<String,Object>i=new LinkedHashMap<>();i.put("sequence_no",1);i.put("location_code","A01");i.put("container_number","C1");i.put("fc_code","LAX9");i.put("marking","M");i.put("planned_pallet_qty","12.50");i.put("planned_carton_qty","20");i.put("planned_weight_lbs","100.25");i.put("planned_cbm","2.5");try(var b=new XSSFWorkbook(new ByteArrayInputStream(PickingBolService.workbook(p,List.of(i))))){var s=b.getSheet("Picking List");assertThat(PickingBolService.HEADERS).hasSize(11);for(int x=0;x<11;x++)assertThat(s.getRow(0).getCell(x).getStringCellValue()).isEqualTo(PickingBolService.HEADERS.get(x));assertThat(s.getRow(1).getCell(7).getCellType()).isEqualTo(CellType.STRING);assertThat(s.getRow(1).getCell(7).getStringCellValue()).isEqualTo("12.50");}}}
